        try c.encode(deleted, forKey: .deleted)
        try c.encode(entriesRemoved, forKey: .entriesRemoved)
        try c.encode(projectsDeleted, forKey: .projectsDeleted)
        try c.encode(tokensRemoved, forKey: .tokensRemoved)
    }
}

