    ) {
        self.email = email
        self.entries = entries
        self.ownedProjects = ownedProjects
        self.tokens = tokens
        self.userId = userId
    }

    enum CodingKeys: String, CodingKey {
        case email = "email"
        case entries = "entries"
        case ownedProjects = "ownedProjects"
        case tokens = "tokens"
        case userId = "userId"
    }

    public init(from decoder: Decoder) throws {
